import React, { useMemo, useRef, useState, useEffect } from "react";
import { T } from "../theme";
import { SerieTag } from "../pjMeta";
import { STEP_KEYS, STEP_LABEL, STEP_IS_MS, nodeKey, splitKey, dayNum, isoOfDay, setStep, shiftPj } from "./engine";

export const fmtIso = iso => iso ? iso.slice(8, 10) + "/" + iso.slice(5, 7) + "/" + iso.slice(2, 4) : "—";
const PJ_H = 30, STEP_H = 24, LEFT_W = 290, HEAD_H = 34;
const STEP_COLOR = { arrivee: "#B08D57", production: "#2B9C78", tests: "#7C63B8", finProd: "#1E2C66", depart: "#CB4848" };
const MONTHS = ["Janv", "Fév", "Mars", "Avr", "Mai", "Juin", "Juil", "Août", "Sept", "Oct", "Nov", "Déc"];

// Diagramme de Gantt modifiable : glisser une barre = date imposée (« pas avant »), poignée de droite = durée,
// glisser la barre de synthèse d'un PJ = décaler tout le PJ. Les liens du PJ sélectionné sont tracés.
export function PlannerGantt({ plan, sched, cal, closurePeriods, pjs, sel, setSel, exp, toggleExp, px, onPreview, onCommit }) {
  const rows = useMemo(() => {
    const out = []; let y = 0;
    pjs.forEach(p => {
      out.push({ type: "pj", p, y, h: PJ_H }); y += PJ_H;
      if (exp.has(p.pj)) STEP_KEYS.filter(k => p.steps[k]).forEach(k => { out.push({ type: "step", p, k, y, h: STEP_H }); y += STEP_H; });
    });
    return { list: out, height: y };
  }, [pjs, exp]);

  const range = useMemo(() => {
    let lo = Infinity, hi = -Infinity;
    Object.values(sched.nodes).forEach(n => { if (n.s === null) return; lo = Math.min(lo, dayNum(n.start)); hi = Math.max(hi, dayNum(n.finish)); });
    const today = dayNum(new Date().toISOString().slice(0, 10));
    if (!isFinite(lo)) { lo = today - 14; hi = today + 120; }
    lo = Math.min(lo, today - 7); hi = Math.max(hi, today + 30);
    lo -= 7; lo -= ((new Date(lo * 86400000).getUTCDay() + 6) % 7); // retombe sur un lundi
    hi += 21; return { lo, hi, today };
  }, [sched]);
  const W = (range.hi - range.lo + 1) * px;
  const X = iso => (dayNum(iso) - range.lo) * px;

  // en-tête : mois
  const months = useMemo(() => {
    const out = []; let n = range.lo;
    while (n <= range.hi) {
      const d = new Date(n * 86400000); const y = d.getUTCFullYear(), m = d.getUTCMonth();
      const nextStart = Date.UTC(y, m + 1, 1) / 86400000; const end = Math.min(range.hi + 1, nextStart);
      out.push({ label: MONTHS[m] + (m === 0 || out.length === 0 ? " " + String(y).slice(2) : ""), x: (n - range.lo) * px, w: (end - n) * px });
      n = nextStart;
    }
    return out;
  }, [range, px]);

  // ── glisser-déposer ──
  const drag = useRef(null);
  const [dragging, setDragging] = useState(false);
  useEffect(() => {
    if (!dragging) return;
    const move = e => {
      const d = drag.current; if (!d) return;
      const dd = Math.round((e.clientX - d.x0) / px);
      if (dd === d.dd) return; d.dd = dd;
      if (dd === 0) { onPreview(null); return; }
      let cand = null;
      if (d.kind === "move") {
        const s = cal.dateOf(cal.idxOnOrAfter(isoOfDay(dayNum(d.node.start) + dd)));
        cand = setStep(d.base, d.pj, d.step, { snet: s });
      } else if (d.kind === "resize") {
        const nf = isoOfDay(dayNum(d.node.finish) + dd);
        cand = setStep(d.base, d.pj, d.step, { dur: Math.max(1, cal.countBetween(d.node.start, nf)) });
      } else if (d.kind === "pj") {
        const target = cal.dateOf(cal.idxOnOrAfter(isoOfDay(dayNum(d.startIso) + dd)));
        const wd = cal.idxOnOrAfter(target) - cal.idxOnOrAfter(d.startIso);
        const p = d.base.pjs.find(x => x.pj === d.pj);
        const hasSnet = Object.values(p.steps).some(st => st && st.snet);
        cand = hasSnet ? shiftPj(d.base, d.pj, wd, cal) : setStep(d.base, d.pj, STEP_KEYS.find(k => p.steps[k]), { snet: target });
      }
      d.cand = cand; onPreview(cand);
    };
    const up = () => {
      const d = drag.current; drag.current = null; setDragging(false);
      if (!d) return;
      if (d.dd && d.cand) {
        const want = d.kind === "move" ? cal.dateOf(cal.idxOnOrAfter(isoOfDay(dayNum(d.node.start) + d.dd))) : null;
        onCommit(d.cand, want ? { key: nodeKey(d.pj, d.step), want } : null);
      } else onPreview(null);
    };
    window.addEventListener("mousemove", move); window.addEventListener("mouseup", up);
    return () => { window.removeEventListener("mousemove", move); window.removeEventListener("mouseup", up); };
  }, [dragging, px, cal, onPreview, onCommit]);
  const startDrag = (e, d) => { e.preventDefault(); e.stopPropagation(); drag.current = { ...d, x0: e.clientX, dd: 0, base: plan }; setDragging(true); };

  // ── liens du PJ sélectionné ──
  const yOf = useMemo(() => { const m = {}; rows.list.forEach(r => { m[r.type === "pj" ? r.p.pj : nodeKey(r.p.pj, r.k)] = r.y + r.h / 2; }); return m; }, [rows]);
  const links = useMemo(() => {
    if (!sel) return [];
    return (plan.links || []).filter(l => splitKey(l.from).pj === sel.pj || splitKey(l.to).pj === sel.pj).map(l => {
      const a = sched.nodes[l.from], b = sched.nodes[l.to]; if (!a || !b || a.s === null || b.s === null) return null;
      const ya = yOf[l.from] != null ? yOf[l.from] : yOf[a.pj], yb = yOf[l.to] != null ? yOf[l.to] : yOf[b.pj]; if (ya == null || yb == null) return null;
      const x1 = (l.type === "FS" || l.type === "FF") ? X(a.finish) + px : X(a.start) + (a.ms ? px / 2 : 0);
      const x2 = (l.type === "FS" || l.type === "SS") ? X(b.start) + (b.ms ? px / 2 : 0) : X(b.finish) + px;
      return { id: l.id, x1: (a.ms && (l.type === "FS" || l.type === "FF")) ? X(a.start) + px / 2 : x1, y1: ya, x2, y2: yb };
    }).filter(Boolean);
  }, [plan, sched, sel, yOf, px, range.lo]); // eslint-disable-line react-hooks/exhaustive-deps

  const closures = (closurePeriods || []).map(c => ({ x: X(c.start), w: (dayNum(c.end || c.start) - dayNum(c.start) + 1) * px, label: c.label })).filter(c => c.x + c.w > 0 && c.x < W);

  return (<div style={{ display: "flex", minWidth: "min-content", position: "relative", userSelect: dragging ? "none" : "auto", cursor: dragging ? "grabbing" : "default" }}>
    {/* colonne gauche : libellés */}
    <div style={{ width: LEFT_W, flexShrink: 0, position: "sticky", left: 0, zIndex: 6, background: T.card, borderRight: "1px solid " + T.line }}>
      <div style={{ height: HEAD_H, position: "sticky", top: 0, zIndex: 7, background: T.surface, borderBottom: "1px solid " + T.line, display: "flex", alignItems: "center", padding: "0 10px", fontSize: 11.5, fontWeight: 700, color: T.ink500, textTransform: "uppercase", letterSpacing: ".05em" }}>PJ / étapes (ordre de priorité)</div>
      {rows.list.map(r => {
        if (r.type === "pj") {
          const on = sel && sel.pj === r.p.pj && !sel.step; const open = exp.has(r.p.pj); const idx = pjs.indexOf(r.p) + 1;
          return (<div key={"p" + r.p.pj} onClick={() => setSel({ pj: r.p.pj, step: null })} style={{ height: r.h, display: "flex", alignItems: "center", gap: 6, padding: "0 8px", borderBottom: "1px solid " + T.line, background: on ? T.teal100 : T.card, cursor: "pointer", boxSizing: "border-box" }}>
            <span onClick={e => { e.stopPropagation(); toggleExp(r.p.pj); }} style={{ width: 16, color: T.ink500, fontSize: 11, textAlign: "center" }}>{open ? "▾" : "▸"}</span>
            <span style={{ fontSize: 10.5, color: T.ink300, width: 20, textAlign: "right" }}>{idx}</span>
            <span style={{ fontFamily: T.fontMono, fontWeight: 700, fontSize: 13, color: T.teal600, whiteSpace: "nowrap" }}>{r.p.pj}</span>
            <SerieTag pj={r.p.pj} size={9.5} />
            <span style={{ fontSize: 12, color: T.ink500, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap", minWidth: 0 }}>{r.p.nomProjet || ""}</span>
          </div>);
        }
        const key = nodeKey(r.p.pj, r.k), n = sched.nodes[key]; const on = sel && sel.pj === r.p.pj && sel.step === r.k;
        const hasIn = (plan.links || []).some(l => l.to === key), hasOut = (plan.links || []).some(l => l.from === key);
        return (<div key={key} onClick={() => setSel({ pj: r.p.pj, step: r.k })} style={{ height: r.h, display: "flex", alignItems: "center", gap: 6, padding: "0 8px 0 50px", borderBottom: "1px solid " + T.line, background: on ? T.teal100 : T.card, cursor: "pointer", boxSizing: "border-box", fontSize: 12 }}>
          <span style={{ width: 8, height: 8, borderRadius: STEP_IS_MS[r.k] ? 2 : 4, transform: STEP_IS_MS[r.k] ? "rotate(45deg)" : "none", background: STEP_COLOR[r.k], flexShrink: 0 }} />
          <span style={{ color: T.ink700, fontWeight: 600, whiteSpace: "nowrap" }}>{STEP_LABEL[r.k]}</span>
          {(hasIn || hasOut) && <span title={(hasIn ? "a un prédécesseur" : "") + (hasIn && hasOut ? " · " : "") + (hasOut ? "a un successeur" : "")} style={{ fontSize: 10, color: T.ink300 }}>⛓</span>}
          <span style={{ marginLeft: "auto", fontFamily: T.fontMono, fontSize: 11, color: T.ink500 }}>{n && n.s !== null ? fmtIso(n.start) : "—"}</span>
        </div>);
      })}
    </div>
    {/* zone temps */}
    <div style={{ width: W, flexShrink: 0, position: "relative" }}>
      <div style={{ height: HEAD_H, position: "sticky", top: 0, zIndex: 5, background: T.surface, borderBottom: "1px solid " + T.line }}>
        {months.map((m, i) => <div key={i} style={{ position: "absolute", left: m.x, width: m.w, top: 0, bottom: 0, borderLeft: "1px solid " + T.line, padding: "9px 6px", fontSize: 11.5, fontWeight: 700, color: T.ink500, whiteSpace: "nowrap", overflow: "hidden", boxSizing: "border-box" }}>{m.label}</div>)}
      </div>
      <div style={{ position: "relative", height: rows.height, backgroundImage: "repeating-linear-gradient(90deg, transparent 0, transparent " + (5 * px) + "px, rgba(120,120,120,.08) " + (5 * px) + "px, rgba(120,120,120,.08) " + (7 * px) + "px)", backgroundSize: (7 * px) + "px 100%" }}>
        {closures.map((c, i) => <div key={i} title={c.label} style={{ position: "absolute", left: c.x, width: c.w, top: 0, bottom: 0, background: "rgba(193,131,30,.13)" }} />)}
        {months.map((m, i) => <div key={"g" + i} style={{ position: "absolute", left: m.x, top: 0, bottom: 0, width: 1, background: T.line, opacity: .7 }} />)}
        <div title="Aujourd'hui" style={{ position: "absolute", left: (range.today - range.lo) * px + px / 2, top: 0, bottom: 0, width: 2, background: "#CB4848", opacity: .65, zIndex: 3 }} />
        {rows.list.map(r => {
          const rowStyle = { position: "absolute", left: 0, right: 0, top: r.y, height: r.h, borderBottom: "1px solid " + T.line, boxSizing: "border-box" };
          if (r.type === "pj") {
            const ns = STEP_KEYS.map(k => sched.nodes[nodeKey(r.p.pj, k)]).filter(n => n && n.s !== null);
            if (!ns.length) return <div key={"p" + r.p.pj} style={rowStyle} />;
            const a = Math.min(...ns.map(n => dayNum(n.start))), b = Math.max(...ns.map(n => dayNum(n.finish)));
            const startIso = isoOfDay(a); const on = sel && sel.pj === r.p.pj;
            return (<div key={"p" + r.p.pj} style={rowStyle}>
              <div title={r.p.pj + " : " + fmtIso(startIso) + " → " + fmtIso(isoOfDay(b)) + " (glisser pour décaler tout le PJ)"} onMouseDown={e => startDrag(e, { kind: "pj", pj: r.p.pj, startIso })} onClick={() => setSel({ pj: r.p.pj, step: null })}
                style={{ position: "absolute", left: X(startIso), width: Math.max(px, (b - a + 1) * px), top: 11, height: 8, borderRadius: 4, background: on ? T.navy700 : "#8C97B8", cursor: "grab" }} />
              {ns.filter(n => n.ms).map(n => <span key={n.step} style={{ position: "absolute", left: X(n.start) + px / 2 - 5, top: 10, width: 10, height: 10, transform: "rotate(45deg)", background: STEP_COLOR[n.step], border: "1px solid #fff", pointerEvents: "none" }} />)}
            </div>);
          }
          const key = nodeKey(r.p.pj, r.k), n = sched.nodes[key]; const on = sel && sel.pj === r.p.pj && sel.step === r.k;
          if (!n || n.s === null) return <div key={key} style={rowStyle} />;
          const col = STEP_COLOR[r.k];
          const tip = STEP_LABEL[r.k] + " : " + fmtIso(n.start) + (n.ms ? "" : " → " + fmtIso(n.finish) + " (" + n.dur + " j ouvrés)") + (n.driver === "snet" ? " · date imposée" : n.driver ? " · calée par un lien" : "") + (n.snetIgnored ? " · date imposée sans effet (un lien est plus tardif)" : "");
          return (<div key={key} style={rowStyle}>
            {n.ms
              ? <div title={tip} onMouseDown={e => startDrag(e, { kind: "move", pj: r.p.pj, step: r.k, node: n })} onClick={() => setSel({ pj: r.p.pj, step: r.k })}
                  style={{ position: "absolute", left: X(n.start) + px / 2 - 7, top: 5, width: 14, height: 14, transform: "rotate(45deg)", background: col, border: on ? "2px solid " + T.ink900 : "1px solid #fff", boxSizing: "border-box", cursor: "grab" }} />
              : <div title={tip} onMouseDown={e => startDrag(e, { kind: "move", pj: r.p.pj, step: r.k, node: n })} onClick={() => setSel({ pj: r.p.pj, step: r.k })}
                  style={{ position: "absolute", left: X(n.start), width: Math.max(px, (dayNum(n.finish) - dayNum(n.start) + 1) * px), top: 4, height: 16, borderRadius: 4, background: col, outline: on ? "2px solid " + T.ink900 : "none", cursor: "grab", display: "flex", alignItems: "center", justifyContent: "center", color: "#fff", fontSize: 10.5, fontWeight: 700, overflow: "hidden" }}>
                  <span style={{ pointerEvents: "none" }}>{n.dur} j</span>
                  <div onMouseDown={e => startDrag(e, { kind: "resize", pj: r.p.pj, step: r.k, node: n })} style={{ position: "absolute", right: 0, top: 0, bottom: 0, width: 7, cursor: "ew-resize", background: "rgba(0,0,0,.18)" }} />
                </div>}
            {n.driver === "snet" && <span title="date imposée" style={{ position: "absolute", left: X(n.start) - 11, top: 6, fontSize: 10, pointerEvents: "none" }}>📌</span>}
          </div>);
        })}
        <svg width={W} height={rows.height} style={{ position: "absolute", left: 0, top: 0, pointerEvents: "none", zIndex: 4 }}>
          <defs><marker id="plan-arrow" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto"><path d="M0,0 L8,4 L0,8 z" fill="#CB4848" /></marker></defs>
          {links.map(l => <path key={l.id} d={"M" + l.x1 + "," + l.y1 + " H" + (l.x1 + 7) + " V" + l.y2 + " H" + l.x2} fill="none" stroke="#CB4848" strokeWidth="1.6" markerEnd="url(#plan-arrow)" opacity=".85" />)}
        </svg>
      </div>
    </div>
  </div>);
}
