import React, { useState, useMemo, useEffect, useRef, useCallback } from "react";
import { T } from "../theme";
import { NavIcon, useSheetJS } from "../components/SharedUI";
import { guessGamme } from "../parsers";
import { CARD } from "../components/ManagerParts";
import {
  STEPS, STEP_KEYS, STEP_LABEL, STEP_IS_MS, LINK_TYPES, nodeKey, splitKey, makeCalendar, schedule, planToRows, diffRows, initPlanFromRows,
  setStep, removeStep, addLink, removeLink, updateLink, movePj, setPjField, shiftPj, addPj, removePj,
} from "./engine";
import { parseMsPlan, compareWithMs, applyCalibration } from "./importPlan";
import { PlannerGantt, fmtIso } from "./PlannerGantt";

// ── Module « Planification » (super admin) : remplace MS Project pour construire le planning d'ordonnancement ──
// Le plan (étapes, durées, liens, priorités) est un brouillon enregistré automatiquement. « Publier » le copie dans le
// planning actuel lu par tous les écrans (avec aperçu des changements, historique et annulation). Le planning INITIAL
// (figé) n'est jamais touché ici.

const INP = { padding: "5px 8px", borderRadius: 8, border: "1px solid " + T.line, background: T.card, color: T.ink900, fontSize: 12.5, fontFamily: T.font, boxSizing: "border-box" };
const BTN = { padding: "6px 12px", borderRadius: 8, border: "1px solid " + T.line, background: T.card, color: T.ink700, fontSize: 12.5, fontWeight: 700, cursor: "pointer", fontFamily: T.font, whiteSpace: "nowrap" };
const BTN_P = { ...BTN, border: "none", background: "linear-gradient(135deg," + T.teal500 + "," + T.navy700 + ")", color: "#fff" };
const LAB = { fontSize: 11, fontWeight: 700, color: T.ink500, textTransform: "uppercase", letterSpacing: ".05em", marginBottom: 4 };
const STEP_LABELS = Object.fromEntries(STEPS.map(s => [s[0], s[1]]));

function Modal({ title, onClose, children, width = 720 }) {
  return (<div onClick={onClose} style={{ position: "fixed", inset: 0, background: "rgba(10,20,30,.45)", zIndex: 10000, display: "flex", alignItems: "center", justifyContent: "center", padding: 16, fontFamily: T.font }}>
    <div onClick={e => e.stopPropagation()} style={{ background: T.card, borderRadius: 16, boxShadow: T.shadowLg, border: "1px solid " + T.line, width: "min(" + width + "px,100%)", maxHeight: "88vh", overflow: "auto", padding: "20px 22px" }}>
      <div style={{ fontFamily: T.fontDisplay, fontWeight: 600, fontSize: 19, color: T.ink900, marginBottom: 10 }}>{title}</div>
      {children}
    </div>
  </div>);
}

// champ numérique / texte validé à la sortie du champ ou avec Entrée
function CommitInput({ value, onCommit, type = "number", width = 70, min, placeholder, disabled }) {
  const [v, setV] = useState(value == null ? "" : String(value));
  useEffect(() => { setV(value == null ? "" : String(value)); }, [value]);
  const done = () => { if (String(value == null ? "" : value) !== v) onCommit(v); };
  return <input type={type} min={min} value={v} disabled={disabled} placeholder={placeholder} onChange={e => setV(e.target.value)} onBlur={done}
    onKeyDown={e => { if (e.key === "Enter") e.currentTarget.blur(); else if (e.key === "Escape") { setV(value == null ? "" : String(value)); e.currentTarget.blur(); } }} style={{ ...INP, width }} />;
}

// Choix d'une étape (PJ + étape)
function NodePicker({ plan, value, onChange, exclude }) {
  const init = value ? splitKey(value) : { pj: "", step: "production" };
  const [pj, setPj] = useState(init.pj); const [step, setSt] = useState(init.step);
  useEffect(() => { if (value) { const s = splitKey(value); setPj(s.pj); setSt(s.step); } }, [value]);
  const p = plan.pjs.find(x => x.pj.toLowerCase() === pj.trim().toLowerCase());
  const steps = p ? STEP_KEYS.filter(k => p.steps[k]) : STEP_KEYS;
  const emit = (pjv, stv) => { const pp = plan.pjs.find(x => x.pj.toLowerCase() === pjv.trim().toLowerCase()); if (pp && pp.steps[stv]) { const k = nodeKey(pp.pj, stv); if (k !== exclude) onChange(k); } };
  return (<span style={{ display: "inline-flex", gap: 4 }}>
    <input list="plan-pjs" value={pj} onChange={e => { setPj(e.target.value); emit(e.target.value, step); }} placeholder="PJ…" style={{ ...INP, width: 92, fontFamily: T.fontMono, fontWeight: 700, borderColor: pj && !p ? T.red500 : T.line }} />
    <select value={step} onChange={e => { setSt(e.target.value); emit(pj, e.target.value); }} style={{ ...INP, width: 118 }}>{steps.map(k => <option key={k} value={k}>{STEP_LABELS[k]}</option>)}</select>
  </span>);
}

function Inspector({ plan, sched, cal, sel, setSel, apply, rows }) {
  const [shiftN, setShiftN] = useState(1); const [np, setNp] = useState({ from: "", type: "FS", lag: 0 }); const [msg, setMsg] = useState("");
  const selPjId = sel ? sel.pj : null, selStepId = sel ? sel.step : null;
  useEffect(() => { setMsg(""); setNp({ from: "", type: "FS", lag: 0 }); }, [selPjId, selStepId]);
  const p = sel && plan.pjs.find(x => x.pj === sel.pj);
  if (!sel || !p) return (<div style={{ ...CARD, padding: 16, fontSize: 13, color: T.ink500, lineHeight: 1.6 }}>
    <div style={{ fontFamily: T.fontDisplay, fontWeight: 600, fontSize: 15, color: T.ink900, marginBottom: 6 }}>Détail</div>
    Cliquez sur un PJ ou une étape dans le diagramme.<br /><br />
    <b>Glisser une barre</b> : impose la date de début (« pas avant »).<br /><b>Poignée de droite</b> : change la durée.<br /><b>Glisser la barre grise d'un PJ</b> : décale tout le PJ.<br />Les étapes reliées se recalculent automatiquement.
  </div>);
  const setBad = m => setMsg(m);
  const tryLinks = (nplan, okMsg) => { const s = schedule(nplan, cal); if (s.cycle) { setBad("Impossible : ce lien créerait une boucle (" + s.cycle.slice(0, 3).map(label).join(" → ") + "…)."); return false; } setMsg(okMsg || ""); apply(nplan); return true; };
  const key = sel.step ? nodeKey(p.pj, sel.step) : null; const n = key ? sched.nodes[key] : null;
  const preds = key ? (plan.links || []).filter(l => l.to === key) : []; const succs = key ? (plan.links || []).filter(l => l.from === key) : [];
  const idx = plan.pjs.indexOf(p); const missing = STEP_KEYS.filter(k => !p.steps[k]);
  const label = k => { const s = splitKey(k); return s.pj + " · " + STEP_LABELS[s.step]; };
  const driverText = !n || n.s === null ? "Pas de date : donnez une date imposée ou un prédécesseur."
    : n.driver === "snet" ? "Date imposée (📌)." : n.driver ? "Calée par le lien « " + (() => { const l = (plan.links || []).find(x => x.id === n.driver); return l ? label(l.from) + " (" + l.type + (l.lag ? (l.lag > 0 ? "+" : "") + l.lag + " j" : "") + ")" : "…"; })() + " »." : "";
  return (<div style={{ ...CARD, padding: 16, display: "flex", flexDirection: "column", gap: 14 }}>
    {/* PJ */}
    <div>
      <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
        <span style={{ fontFamily: T.fontMono, fontWeight: 700, fontSize: 18, color: T.teal600 }}>{p.pj}</span>
        <span style={{ fontSize: 13, color: T.ink500, flex: 1, minWidth: 0, overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{p.nomProjet || ""}</span>
        <span title="Priorité" style={{ fontSize: 12, fontWeight: 700, color: T.ink500 }}>#{idx + 1}</span>
        <button title="Monter dans l'ordre de priorité" disabled={idx === 0} onClick={() => apply(movePj(plan, p.pj, -1))} style={{ ...BTN, padding: "3px 8px" }}>▲</button>
        <button title="Descendre dans l'ordre de priorité" disabled={idx === plan.pjs.length - 1} onClick={() => apply(movePj(plan, p.pj, 1))} style={{ ...BTN, padding: "3px 8px" }}>▼</button>
      </div>
      <div style={{ display: "flex", gap: 10, marginTop: 10, flexWrap: "wrap" }}>
        <div><div style={LAB}>Heures Atelier</div><CommitInput value={p.hAt || 0} min={0} onCommit={v => apply(setPjField(plan, p.pj, { hAt: Math.max(0, Number(v) || 0) }))} /></div>
        <div><div style={LAB}>Heures Autom</div><CommitInput value={p.hAu || 0} min={0} onCommit={v => apply(setPjField(plan, p.pj, { hAu: Math.max(0, Number(v) || 0) }))} /></div>
        <div style={{ flex: 1, minWidth: 150 }}><div style={LAB}>Décaler le PJ (jours ouvrés)</div>
          <span style={{ display: "inline-flex", gap: 4, alignItems: "center" }}>
            <input type="number" min={1} value={shiftN} onChange={e => setShiftN(Math.max(1, Number(e.target.value) || 1))} style={{ ...INP, width: 56 }} />
            <button style={BTN} onClick={() => apply(shiftPj(plan, p.pj, -shiftN, cal))}>Avancer</button>
            <button style={BTN} onClick={() => apply(shiftPj(plan, p.pj, shiftN, cal))}>Reculer</button>
          </span></div>
      </div>
      {missing.length > 0 && <div style={{ marginTop: 10, display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center", fontSize: 12, color: T.ink500 }}>Ajouter une étape :
        {missing.map(k => <button key={k} style={{ ...BTN, padding: "3px 9px" }} onClick={() => { apply(setStep(plan, p.pj, k, { dur: STEP_IS_MS[k] ? 0 : 5 })); setSel({ pj: p.pj, step: k }); }}>＋ {STEP_LABELS[k]}</button>)}</div>}
    </div>
    {/* Étape */}
    {sel.step && p.steps[sel.step] && <div style={{ borderTop: "1px solid " + T.line, paddingTop: 12 }}>
      <div style={{ fontWeight: 700, fontSize: 14, color: T.ink900, marginBottom: 2 }}>{STEP_LABEL[sel.step]}</div>
      <div style={{ fontSize: 12.5, color: T.ink500, marginBottom: 8 }}>{n && n.s !== null ? "Début " + fmtIso(n.start) + (n.ms ? "" : " · fin " + fmtIso(n.finish)) : "Non planifiée"}<br />{driverText}{n && n.snetIgnored ? " La date imposée est antérieure à ce que permettent les liens : elle n'a pas d'effet." : ""}</div>
      <div style={{ display: "flex", gap: 14, flexWrap: "wrap", alignItems: "flex-end" }}>
        {!STEP_IS_MS[sel.step] && <div><div style={LAB}>Durée (jours ouvrés)</div><CommitInput value={p.steps[sel.step].dur} min={1} onCommit={v => apply(setStep(plan, p.pj, sel.step, { dur: Math.max(1, Math.round(Number(v)) || 1) }))} /></div>}
        <div><div style={LAB}>Date imposée (pas avant)</div>
          <span style={{ display: "inline-flex", gap: 6, alignItems: "center" }}>
            <input type="checkbox" checked={!!p.steps[sel.step].snet} onChange={e => apply(setStep(plan, p.pj, sel.step, { snet: e.target.checked ? ((n && n.start) || new Date().toISOString().slice(0, 10)) : null }))} />
            <input type="date" disabled={!p.steps[sel.step].snet} value={p.steps[sel.step].snet || ""} onChange={e => e.target.value && apply(setStep(plan, p.pj, sel.step, { snet: e.target.value }))} style={INP} />
          </span></div>
      </div>
      {/* Prédécesseurs */}
      <div style={{ marginTop: 14 }}>
        <div style={LAB}>Prédécesseurs ({preds.length})</div>
        {preds.length === 0 && <div style={{ fontSize: 12.5, color: T.ink300, marginBottom: 6 }}>Aucun : l'étape ne dépend d'aucune autre.</div>}
        {preds.map(l => (<div key={l.id} style={{ display: "flex", gap: 6, alignItems: "center", marginBottom: 6, flexWrap: "wrap" }}>
          <NodePicker plan={plan} value={l.from} exclude={key} onChange={k => tryLinks(updateLink(plan, l.id, { from: k }))} />
          <select value={l.type} onChange={e => tryLinks(updateLink(plan, l.id, { type: e.target.value }))} style={{ ...INP, width: 58 }}>{LINK_TYPES.map(t => <option key={t}>{t}</option>)}</select>
          <span style={{ fontSize: 11, color: T.ink500 }}>décalage</span><CommitInput value={l.lag || 0} width={52} onCommit={v => tryLinks(updateLink(plan, l.id, { lag: Math.round(Number(v)) || 0 }))} />
          <button title="Supprimer ce lien" onClick={() => apply(removeLink(plan, l.id))} style={{ ...BTN, padding: "3px 8px", color: T.red500 }}>✕</button>
        </div>))}
        <div style={{ display: "flex", gap: 6, alignItems: "center", flexWrap: "wrap", paddingTop: 6, borderTop: preds.length ? "1px dashed " + T.line : "none" }}>
          <NodePicker plan={plan} value={np.from} exclude={key} onChange={k => setNp(s => ({ ...s, from: k }))} />
          <select value={np.type} onChange={e => setNp(s => ({ ...s, type: e.target.value }))} style={{ ...INP, width: 58 }}>{LINK_TYPES.map(t => <option key={t}>{t}</option>)}</select>
          <CommitInput value={np.lag} width={52} onCommit={v => setNp(s => ({ ...s, lag: Math.round(Number(v)) || 0 }))} />
          <button style={BTN_P} disabled={!np.from} onClick={() => { if (tryLinks(addLink(plan, { from: np.from, to: key, type: np.type, lag: np.lag }), "Lien ajouté.")) setNp({ from: "", type: "FS", lag: 0 }); }}>＋ Ajouter</button>
        </div>
        <div style={{ fontSize: 11, color: T.ink300, marginTop: 4 }}>FS = fin → début · SS = début → début · FF = fin → fin · SF = début → fin. Décalage en jours ouvrés (négatif = chevauchement).</div>
        {msg && <div style={{ fontSize: 12.5, color: msg.startsWith("Impossible") ? T.red500 : T.emerald600, fontWeight: 700, marginTop: 6 }}>{msg}</div>}
      </div>
      {succs.length > 0 && <div style={{ marginTop: 12 }}><div style={LAB}>Successeurs ({succs.length})</div>
        {succs.map(l => { const s = splitKey(l.to); return <div key={l.id} style={{ fontSize: 12.5, color: T.ink700, marginBottom: 3 }}><button onClick={() => setSel({ pj: s.pj, step: s.step })} style={{ cursor: "pointer", color: T.teal600, fontWeight: 700, background: "none", border: "none", padding: 0, fontSize: 12.5, fontFamily: T.font }}>{label(l.to)}</button> <span style={{ color: T.ink500 }}>({l.type}{l.lag ? (l.lag > 0 ? "+" : "") + l.lag + " j" : ""})</span></div>; })}</div>}
      <button onClick={() => { if (window.confirm("Supprimer l'étape « " + STEP_LABEL[sel.step] + " » de " + p.pj + " (et ses liens) ?")) { apply(removeStep(plan, p.pj, sel.step)); setSel({ pj: p.pj, step: null }); } }} style={{ ...BTN, marginTop: 12, color: T.red500 }}>Supprimer l'étape</button>
    </div>}
    <div style={{ borderTop: "1px solid " + T.line, paddingTop: 10 }}>
      <button onClick={() => { if (window.confirm("Retirer " + p.pj + " du plan ? (Le planning actuel publié n'est pas modifié.)")) { apply(removePj(plan, p.pj)); setSel(null); } }} style={{ ...BTN, color: T.red500 }}>Retirer ce PJ du plan</button>
    </div>
  </div>);
}

// ── Import d'un export MS Project (avec prédécesseurs) ──
function mergePlans(old, imp, mode) {
  if (mode === "replace" || !old) return { ...imp, cal: (old && old.cal) || imp.cal };
  const replaced = new Set(imp.pjs.map(p => p.pj));
  const kept = old.pjs.map(p => replaced.has(p.pj) ? imp.pjs.find(x => x.pj === p.pj) : p);
  const added = imp.pjs.filter(p => !old.pjs.some(o => o.pj === p.pj));
  const oldLinks = (old.links || []).filter(l => !replaced.has(splitKey(l.from).pj) && !replaced.has(splitKey(l.to).pj));
  return { ...old, pjs: [...kept, ...added], links: [...oldLinks, ...imp.links] };
}
function ImportDialog({ cal, rows, plan, onClose, onApply }) {
  useSheetJS();
  const [err, setErr] = useState(""); const [res, setRes] = useState(null); const [mode, setMode] = useState(plan && plan.pjs.length ? "merge" : "replace"); const [calib, setCalib] = useState(true);
  const onFile = async f => {
    setErr(""); setRes(null); if (!f) return;
    try {
      if (!window.XLSX) { setErr("Librairie Excel en cours de chargement, réessayez dans 2 s."); return; }
      const wb = window.XLSX.read(await f.arrayBuffer(), { type: "array" });
      const data = window.XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]], { header: 1, raw: false });
      const parsed = parseMsPlan(data, cal, rows);
      if (!parsed || !parsed.plan.pjs.length) { setErr("Aucun PJ reconnu. Colonnes attendues : Nom, Début (+ ID, Durée, Fin, Prédécesseurs, Niveau hiérarchique)."); return; }
      setRes({ ...parsed, diffs: compareWithMs(parsed.plan, parsed.msDates, cal), name: f.name });
    } catch (e) { console.error(e); setErr("Lecture impossible : " + e.message); }
  };
  const fixable = res ? res.diffs.filter(d => d.fixable).length : 0, notFixable = res ? res.diffs.length - fixable : 0;
  const finalPlan = res ? mergePlans(plan, calib ? applyCalibration(res.plan, res.diffs) : res.plan, mode) : null;
  return (<Modal title="Importer un export MS Project (avec les liens)" onClose={onClose} width={760}>
    <div style={{ fontSize: 13.5, color: T.ink500, lineHeight: 1.55 }}>Export Excel avec les colonnes <b>ID, Nom, Durée, Début, Fin, Prédécesseurs, Niveau hiérarchique</b> (niveau 1 = PJ, niveau 2 = Arrivée / Production / Tests / Fin de production / Départ). Les liens sont repris tels quels.</div>
    <input type="file" accept=".xlsx,.xls" onChange={e => onFile(e.target.files[0])} style={{ margin: "12px 0", fontSize: 13 }} />
    {err && <div style={{ color: T.red500, fontWeight: 700, fontSize: 13 }}>{err}</div>}
    {res && <div style={{ fontSize: 13.5, color: T.ink700, lineHeight: 1.6 }}>
      <div style={{ display: "flex", gap: 8, flexWrap: "wrap", margin: "4px 0 10px" }}>
        {[[res.report.pjCount, "PJ"], [res.report.stepCount, "étapes"], [res.report.linkCount, "liens"]].map(([v, l]) => <span key={l} style={{ background: T.teal100, color: T.teal600, borderRadius: 99, padding: "3px 12px", fontWeight: 700, fontSize: 12.5 }}>{v} {l}</span>)}
      </div>
      {res.report.warnings.slice(0, 6).map((w, i) => <div key={i} style={{ color: T.amber600, fontSize: 12.5 }}>⚠ {w}</div>)}
      {res.report.ignoredLinks.length > 0 && <details style={{ margin: "6px 0" }}><summary style={{ cursor: "pointer", color: T.amber600, fontWeight: 700, fontSize: 12.5 }}>{res.report.ignoredLinks.length} lien(s) non repris (vers des tâches hors Arrivée / Production / Tests / Fin de production / Départ)</summary>
        {res.report.ignoredLinks.slice(0, 20).map((l, i) => <div key={i} style={{ fontSize: 12, color: T.ink500 }}>{l.from} → {l.to}</div>)}</details>}
      {res.diffs.length > 0 && <div style={{ margin: "8px 0", padding: "8px 10px", background: T.amber100, borderRadius: 8, fontSize: 12.5 }}>
        <b>{res.diffs.length} étape(s)</b> ont une date calculée différente de celle de MS Project ({fixable} calculée(s) plus tôt, {notFixable} plus tard — sans doute un calendrier ou un lien interprété différemment).
        {res.diffs.slice(0, 5).map(d => <div key={d.key} style={{ color: T.ink700 }}>{d.key.replace("|", " · ")} : MS {fmtIso(d.ms)} → calcul {fmtIso(d.calc)}</div>)}
        {fixable > 0 && <label style={{ display: "flex", gap: 6, alignItems: "center", marginTop: 6, fontWeight: 700 }}><input type="checkbox" checked={calib} onChange={e => setCalib(e.target.checked)} />Caler les {fixable} étapes calculées trop tôt sur les dates MS Project (date imposée)</label>}
      </div>}
      {res.diffs.length === 0 && <div style={{ color: T.emerald600, fontWeight: 700, fontSize: 12.5, margin: "6px 0" }}>✓ Toutes les dates calculées correspondent à celles de MS Project.</div>}
      {plan && plan.pjs.length > 0 && <div style={{ display: "flex", gap: 14, margin: "8px 0", fontSize: 13 }}>
        <label><input type="radio" checked={mode === "merge"} onChange={() => setMode("merge")} /> Fusionner : remplacer seulement les PJ du fichier</label>
        <label><input type="radio" checked={mode === "replace"} onChange={() => setMode("replace")} /> Tout remplacer</label></div>}
    </div>}
    <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 14 }}>
      <button style={BTN} onClick={onClose}>Annuler</button>
      <button style={BTN_P} disabled={!res} onClick={() => { onApply(finalPlan); onClose(); }}>Importer dans le plan</button>
    </div>
  </Modal>);
}

function PublishDialog({ plan, sched, rows, pubRows, changes, onClose, onPublish }) {
  const [note, setNote] = useState(""); const [busy, setBusy] = useState(false); const [err, setErr] = useState(""); const [done, setDone] = useState(null);
  const byPj = useMemo(() => { const m = {}; changes.forEach(c => { (m[c.pj] = m[c.pj] || []).push(c); }); return m; }, [changes]);
  const unscheduled = Object.values(sched.nodes).filter(n => n.s === null).length;
  const FL = { arrivee: "Arrivée", tests: "Tests", testsFin: "Fin tests", finProd: "Fin prod.", depart: "Départ", heuresAtelier: "Heures atelier", heuresAutom: "Heures autom", new: "Nouveau PJ" };
  const go = async () => { setBusy(true); setErr(""); try { const r = await onPublish(note.trim()); setDone(r); } catch (e) { setErr(e.message || String(e)); } setBusy(false); };
  return (<Modal title="Publier dans le planning actuel" onClose={onClose} width={760}>
    {done ? <div style={{ fontSize: 14, color: T.emerald600, fontWeight: 700 }}>✓ Publié : {done.nChanges} changement(s) appliqués. Tous les écrans utilisent maintenant ces dates.<div style={{ marginTop: 12, textAlign: "right" }}><button style={BTN_P} onClick={onClose}>Fermer</button></div></div> : <>
      <div style={{ fontSize: 13.5, color: T.ink500, lineHeight: 1.55 }}>{changes.length === 0 ? "Le planning actuel est déjà identique au plan : rien à publier." : <>Ces changements remplaceront les dates du planning actuel (calendrier, Gantt, liste, KPI, rapport CODIR). Le planning <b>initial</b> n'est pas modifié. Une copie de l'état actuel est gardée pour pouvoir annuler.</>}</div>
      {unscheduled > 0 && <div style={{ color: T.amber600, fontSize: 12.5, marginTop: 6 }}>⚠ {unscheduled} étape(s) du plan n'ont pas de date (ni date imposée ni prédécesseur) : les dates correspondantes seront vides.</div>}
      {changes.length > 0 && <div style={{ marginTop: 10, border: "1px solid " + T.line, borderRadius: 10, maxHeight: 300, overflow: "auto" }}>
        <table style={{ width: "100%", borderCollapse: "collapse", fontSize: 12.5 }}><tbody>
          {Object.keys(byPj).map(pj => byPj[pj].map((c, i) => (<tr key={pj + i} style={{ borderTop: i === 0 ? "1px solid " + T.line : "none" }}>
            <td style={{ padding: "4px 10px", fontFamily: T.fontMono, fontWeight: 700, color: T.teal600, width: 90 }}>{i === 0 ? pj : ""}</td>
            <td style={{ padding: "4px 10px", color: T.ink500, width: 100 }}>{FL[c.field] || c.field}</td>
            <td style={{ padding: "4px 10px", color: T.ink700 }}>{c.field === "new" ? fmtIso(c.to) : (typeof c.from === "number" ? c.from : fmtIso(c.from)) + " → " + (typeof c.to === "number" ? c.to : fmtIso(c.to))}</td>
          </tr>)))}
        </tbody></table></div>}
      {changes.length > 0 && <input value={note} onChange={e => setNote(e.target.value)} placeholder="Commentaire de publication (facultatif) : ex. « glissement PJ449 suite retard fournisseur »" style={{ ...INP, width: "100%", marginTop: 10 }} />}
      {err && <div style={{ color: T.red500, fontWeight: 700, fontSize: 13, marginTop: 8 }}>{err}</div>}
      <div style={{ display: "flex", justifyContent: "flex-end", gap: 8, marginTop: 14 }}>
        <button style={BTN} onClick={onClose}>Annuler</button>
        <button style={BTN_P} disabled={busy || changes.length === 0 || !!sched.cycle} onClick={go}>{busy ? "Publication…" : "Publier " + changes.length + " changement" + (changes.length > 1 ? "s" : "")}</button>
      </div></>}
  </Modal>);
}

function HistoryDialog({ onClose, onLoad, onRestorePlan, onRestorePub }) {
  const [items, setItems] = useState(null); const [err, setErr] = useState(""); const [msg, setMsg] = useState("");
  useEffect(() => { onLoad().then(setItems).catch(e => setErr(e.message)); }, []); // eslint-disable-line
  return (<Modal title="Historique des publications" onClose={onClose}>
    {err && <div style={{ color: T.red500 }}>{err}</div>}{msg && <div style={{ color: T.emerald600, fontWeight: 700, margin: "6px 0" }}>{msg}</div>}
    {items === null && !err && <div style={{ color: T.ink500 }}>Chargement…</div>}
    {items && items.length === 0 && <div style={{ color: T.ink500, fontSize: 13.5 }}>Aucune publication pour l'instant.</div>}
    {items && items.map(e => (<div key={e.at} style={{ borderTop: "1px solid " + T.line, padding: "10px 0", display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap" }}>
      <div style={{ flex: 1, minWidth: 220 }}><div style={{ fontWeight: 700, fontSize: 13.5, color: T.ink900 }}>{new Date(e.at).toLocaleString("fr-FR")} · {e.by || "—"}</div>
        <div style={{ fontSize: 12.5, color: T.ink500 }}>{e.nChanges} changement(s){e.note ? " · " + e.note : ""}</div></div>
      <button style={BTN} title="Recharge le plan tel qu'il était à cette publication (n'est pas publié automatiquement)" onClick={() => { onRestorePlan(e.plan); setMsg("Plan rechargé dans l'éditeur (non publié)."); }}>Recharger ce plan</button>
      <button style={{ ...BTN, color: T.red500 }} title="Remet dans le planning actuel les dates d'avant cette publication" onClick={async () => { if (!window.confirm("Annuler cette publication et remettre le planning actuel dans son état d'avant ?")) return; try { await onRestorePub(e.at); setMsg("Publication annulée : le planning actuel est revenu à l'état précédent."); } catch (x) { setErr(x.message); } }}>Annuler cette publication</button>
    </div>))}
    <div style={{ textAlign: "right", marginTop: 10 }}><button style={BTN} onClick={onClose}>Fermer</button></div>
  </Modal>);
}

export function PlannerView({ planLoaded, planDoc, rows, closurePeriods, authorName, onSavePlan, onPublish, onLoadHistory, onRestorePublication }) {
  const [plan, setPlanState] = useState(null); const [preview, setPreview] = useState(null);
  const [undo, setUndo] = useState([]); const [redo, setRedo] = useState([]);
  const [sel, setSel] = useState(null); const [exp, setExp] = useState(() => new Set()); const [px, setPx] = useState(7);
  const [q, setQ] = useState(""); const [dlg, setDlg] = useState(null); const [saveSt, setSaveSt] = useState(""); const [notice, setNotice] = useState(""); const [addCode, setAddCode] = useState("");
  const lastSaved = useRef(null);
  const holidays = !(plan && plan.cal && plan.cal.holidays === false);
  const cal = useMemo(() => makeCalendar({ closurePeriods, holidays }), [closurePeriods, holidays]);

  // reprise du plan enregistré (première lecture, ou modification faite ailleurs tant qu'on n'a rien changé ici)
  useEffect(() => {
    if (!planDoc || !planDoc.plan) return;
    const js = JSON.stringify(planDoc.plan);
    if (plan === null) { setPlanState(planDoc.plan); lastSaved.current = js; return; }
    if (js !== lastSaved.current && JSON.stringify(plan) === lastSaved.current) { setPlanState(planDoc.plan); lastSaved.current = js; }
  }, [planDoc]); // eslint-disable-line
  // enregistrement automatique (brouillon partagé)
  useEffect(() => {
    if (!plan) return; const js = JSON.stringify(plan); if (js === lastSaved.current) return;
    setSaveSt("Enregistrement…");
    const t = setTimeout(async () => { try { await onSavePlan(plan); lastSaved.current = js; setSaveSt("Brouillon enregistré ✓"); } catch (e) { console.error(e); setSaveSt("Échec de l'enregistrement"); } }, 900);
    return () => clearTimeout(t);
  }, [plan]); // eslint-disable-line

  const live = preview || plan;
  const sched = useMemo(() => live ? schedule(live, cal) : { nodes: {}, cycle: null }, [live, cal]);
  const pubRows = useMemo(() => plan ? planToRows(plan, schedule(plan, cal), rows || [], guessGamme, cal) : [], [plan, cal, rows]);
  const changes = useMemo(() => plan ? diffRows(rows || [], pubRows) : [], [rows, pubRows, plan]);

  const apply = useCallback(np => { if (!np || np === plan) return; setUndo(u => [...u.slice(-49), plan]); setRedo([]); setPlanState(np); setPreview(null); }, [plan]);
  const doUndo = () => { if (!undo.length) return; setRedo(r => [...r, plan]); setPlanState(undo[undo.length - 1]); setUndo(u => u.slice(0, -1)); };
  const doRedo = () => { if (!redo.length) return; setUndo(u => [...u, plan]); setPlanState(redo[redo.length - 1]); setRedo(r => r.slice(0, -1)); };
  const onCommit = useCallback((np, info) => {
    apply(np); setNotice("");
    if (info) { const n = schedule(np, cal).nodes[info.key]; if (n && n.s !== null && n.start !== info.want) setNotice("Début limité au " + fmtIso(n.start) + " par un lien ou la date imposée : impossible plus tôt."); }
  }, [apply, cal]);
  useEffect(() => { if (!notice) return; const t = setTimeout(() => setNotice(""), 6000); return () => clearTimeout(t); }, [notice]);

  const pjsShown = useMemo(() => { if (!plan) return []; const s = q.trim().toLowerCase(); return plan.pjs.filter(p => !s || p.pj.toLowerCase().includes(s) || (p.nomProjet || "").toLowerCase().includes(s)); }, [plan, q]);
  const toggleExp = pj => setExp(s => { const n = new Set(s); n.has(pj) ? n.delete(pj) : n.add(pj); return n; });

  if (!planLoaded) return <div style={{ ...CARD, padding: 20, color: T.ink500 }}>Chargement du plan…</div>;
  if (!plan) {
    return (<div style={{ ...CARD, padding: 22, maxWidth: 760 }}>
      <div style={{ fontFamily: T.fontDisplay, fontWeight: 600, fontSize: 19, color: T.ink900, display: "flex", gap: 9, alignItems: "center" }}><NavIcon name="plan" size={19} />Planification</div>
      <div style={{ fontSize: 14, color: T.ink500, lineHeight: 1.65, margin: "10px 0 16px" }}>Construisez et faites évoluer le planning d'ordonnancement directement ici, à la place de MS Project : durées, liens entre étapes et entre PJ, priorités, recalcul automatique en cascade, puis publication dans le planning actuel. Le planning initial reste figé comme aujourd'hui.</div>
      <div style={{ display: "flex", gap: 10, flexWrap: "wrap" }}>
        <button style={BTN_P} onClick={() => setPlanState(initPlanFromRows(rows || [], cal))}>Créer le plan depuis le planning actuel ({(rows || []).length} PJ)</button>
        <button style={BTN} onClick={() => setDlg("import")}>Importer un export MS Project (avec liens)</button>
      </div>
      <div style={{ fontSize: 12.5, color: T.ink300, marginTop: 12 }}>Recommandé : importer l'export MS Project avec la colonne « Prédécesseurs » pour reprendre vos liens existants.</div>
      {dlg === "import" && <ImportDialog cal={cal} rows={rows} plan={null} onClose={() => setDlg(null)} onApply={np => setPlanState(np)} />}
    </div>);
  }
  const nLinks = (plan.links || []).length;
  const rowsNotInPlan = (rows || []).filter(r => !plan.pjs.some(p => p.pj === r.pj));
  const selPj = sel && plan.pjs.some(p => p.pj === sel.pj) ? sel : null;
  return (<div style={{ display: "flex", flexDirection: "column", gap: 12, fontFamily: T.font }}>
    <datalist id="plan-pjs">{plan.pjs.map(p => <option key={p.pj} value={p.pj}>{p.nomProjet || ""}</option>)}</datalist>
    {/* barre d'outils */}
    <div style={{ ...CARD, padding: "10px 14px", display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
      <div style={{ fontFamily: T.fontDisplay, fontWeight: 600, fontSize: 16, color: T.ink900, display: "flex", gap: 8, alignItems: "center", marginRight: 4 }}><NavIcon name="plan" size={17} />Planification</div>
      <span style={{ fontSize: 12.5, color: T.ink500 }}>{plan.pjs.length} PJ · {nLinks} lien{nLinks > 1 ? "s" : ""}</span>
      <span style={{ fontSize: 12.5, fontWeight: 700, borderRadius: 99, padding: "3px 11px", background: changes.length ? T.amber100 : T.emerald100, color: changes.length ? T.amber600 : T.emerald600 }}>{changes.length ? changes.length + " modification" + (changes.length > 1 ? "s" : "") + " non publiée" + (changes.length > 1 ? "s" : "") : "À jour avec le planning actuel"}</span>
      <span style={{ fontSize: 12, color: T.ink300 }}>{saveSt}</span>
      <span style={{ flex: 1 }} />
      <input value={q} onChange={e => setQ(e.target.value)} placeholder="Rechercher un PJ…" style={{ ...INP, width: 150 }} />
      <button style={BTN} disabled={!undo.length} onClick={doUndo} title="Annuler">↶</button>
      <button style={BTN} disabled={!redo.length} onClick={doRedo} title="Rétablir">↷</button>
      <button style={BTN} onClick={() => setPx(v => Math.max(3, v - 2))} title="Zoom arrière">−</button>
      <button style={BTN} onClick={() => setPx(v => Math.min(20, v + 2))} title="Zoom avant">＋</button>
      <button style={BTN} onClick={() => setExp(s => s.size ? new Set() : new Set(plan.pjs.map(p => p.pj)))}>{exp.size ? "Tout replier" : "Tout déplier"}</button>
      <label style={{ display: "inline-flex", gap: 5, alignItems: "center", fontSize: 12, color: T.ink500, fontWeight: 600 }} title="Les jours fériés français ne sont pas ouvrés"><input type="checkbox" checked={holidays} onChange={e => apply({ ...plan, cal: { ...(plan.cal || {}), holidays: e.target.checked } })} />Fériés non ouvrés</label>
    </div>
    <div style={{ ...CARD, padding: "8px 14px", display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
      <input list="plan-add" value={addCode} onChange={e => setAddCode(e.target.value)} placeholder="Ajouter un PJ (code)…" style={{ ...INP, width: 170, fontFamily: T.fontMono }} />
      <datalist id="plan-add">{rowsNotInPlan.map(r => <option key={r.pj} value={r.pj} />)}</datalist>
      <button style={BTN} disabled={!addCode.trim()} onClick={() => { const c = addCode.trim().toUpperCase(); apply(addPj(plan, c, (rows || []).find(r => r.pj === c) || null, cal)); setSel({ pj: c, step: null }); setAddCode(""); }}>＋ Ajouter</button>
      <span style={{ flex: 1 }} />
      <button style={BTN} onClick={() => setDlg("import")}>Importer MS Project…</button>
      <button style={BTN} onClick={() => setDlg("history")}>Historique</button>
      <button style={BTN_P} onClick={() => setDlg("publish")}>Publier dans le planning actuel…</button>
    </div>
    {sched.cycle && <div style={{ background: T.red100, color: T.red600, borderRadius: 10, padding: "9px 14px", fontSize: 13, fontWeight: 700 }}>Boucle de liens détectée ({sched.cycle.slice(0, 4).map(k => { const x = splitKey(k); return x.pj + " · " + STEP_LABELS[x.step]; }).join(" → ")}…) : certaines dates ne peuvent pas être calculées. Supprimez un des liens.</div>}
    {notice && <div style={{ background: T.amber100, color: T.amber600, borderRadius: 10, padding: "8px 14px", fontSize: 13, fontWeight: 700 }}>{notice}</div>}
    <div style={{ display: "flex", gap: 12, alignItems: "flex-start", flexWrap: "wrap" }}>
      <div style={{ ...CARD, padding: 0, flex: "1 1 640px", minWidth: 0, overflow: "auto", maxHeight: "calc(100vh - 290px)", minHeight: 320 }}>
        <PlannerGantt plan={plan} sched={sched} cal={cal} closurePeriods={closurePeriods} pjs={pjsShown} sel={selPj} setSel={setSel} exp={exp} toggleExp={toggleExp} px={px} onPreview={setPreview} onCommit={onCommit} />
      </div>
      <div style={{ flex: "0 1 380px", minWidth: 300 }}><Inspector plan={plan} sched={sched} cal={cal} sel={selPj} setSel={setSel} apply={apply} rows={rows} /></div>
    </div>
    {dlg === "import" && <ImportDialog cal={cal} rows={rows} plan={plan} onClose={() => setDlg(null)} onApply={np => apply(np)} />}
    {dlg === "publish" && <PublishDialog plan={plan} sched={sched} rows={rows} pubRows={pubRows} changes={changes} onClose={() => setDlg(null)} onPublish={note => onPublish(plan, note)} />}
    {dlg === "history" && <HistoryDialog onClose={() => setDlg(null)} onLoad={onLoadHistory} onRestorePlan={p => apply(p)} onRestorePub={onRestorePublication} />}
  </div>);
}
